 "content": "from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = [[False] * w for _ in range(h)]
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or seen[r][c]:
                continue
            q = deque([(r, c)])
            seen[r][c] = True
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and not seen[ny][nx] and grid[ny][nx] != 0:
                        seen[ny][nx] = True
                        q.append((ny, nx))
            colors = {}
            for y, x in cells:
                colors.setdefault(grid[y][x], []).append((y, x))
            if len(colors) < 2:
                continue
            # Nested color bands are ordered from outside to inside by the
            # bounding-box area of each color's cells.
            ordered = sorted(colors, key=lambda color: (
                (max(y for y, x in colors[color]) - min(y for y, x in colors[color]) + 1)
                * (max(x for y, x in colors[color]) - min(x for y, x in colors[color]) + 1),
                len(colors[color])
            ), reverse=True)
            mapping = {src: dst for src, dst in zip(ordered, reversed(ordered))}
            for y, x in cells:
                out[y][x] = mapping[grid[y][x]]
    return out
